export type RestPathTemplate = (typeof REST_PATH_TEMPLATES)[number];

/** Fill `{param}` segments. Missing keys throw; values are URI-encoded. */
export function restPath(
  template: RestPathTemplate,
  params: Record<string, string | number> = {},
): string {
  return template.replace(/\{([a-zA-Z_][a-zA-Z0-9_]*)\}/g, (_m, name: string) => {
    if (!(name in params)) {
      throw new Error(`restPath: missing param "${name}" for ${template}`);
    }
    return encodeURIComponent(String(params[name]));
  });
}
